WITH base AS (SELECT *, ROUND(unit_price / quantity, 2) AS line_total, unit_price + quantity AS line_total_2 FROM order_items WHERE product_id IS NOT NULL) SELECT id, product_id, quantity, SUM(unit_price) OVER (PARTITION BY product_id ORDER BY line_total_2, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_unit_price, NTILE(3) OVER (PARTITION BY product_id ORDER BY line_total_2 DESC, id) AS line_total_2_bucket, FIRST_VALUE(unit_price) IGNORE NULLS OVER w_running AS first_known_unit_price FROM base WINDOW w_running AS (PARTITION BY product_id ORDER BY line_total, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
